#include <windows.h>
#include <gdiplus.h>
#include "next/integration/session.hpp"
#include "engine/mechanism_step.hpp"
#include "interop.hpp"
#include <fstream>
#include <iostream>
using namespace r62;using namespace core;using namespace integration;
static void check(Error e){if(!e.ok())throw std::runtime_error(e.message);}
static void saveComponent(const Document& doc,ObjectId atom,const std::string& file){auto component=projection_molecule::component(doc,atom);std::set<ObjectId> ids(component.begin(),component.end());std::vector<ObjectRef> refs;for(auto a:component)refs.emplace_back(ObjectKind::Atom,a);for(const auto& b:doc.bonds().records())if(b.isAlive()&&ids.count(b.beginAtom)&&ids.count(b.endAtom))refs.emplace_back(ObjectKind::Bond,b.id);Document isolated;check(studioio::append(doc,isolated,refs,Vec2(),nullptr));std::string xml;check(studioio::exportXml(isolated,&xml));std::ofstream(file)<<xml;}
int main(int argc,char** argv){if(argc!=3)return 2;Gdiplus::GdiplusStartupInput input;ULONG_PTR token;Gdiplus::GdiplusStartup(&token,&input,0);int code=0;try{
    for(int aMirror=0;aMirror<2;++aMirror)for(int bMirror=0;bMirror<2;++bMirror)for(int view=0;view<5;++view){Session s;check(s.open(std::string(argv[1])+"/projection-mechanism-"+std::to_string(aMirror)+"-"+std::to_string(view)+"-1-source.cdxml"));ObjectId br=kInvalidObjectId;for(const auto& a:s.doc.atoms().records())if(a.isAlive()&&a.element==35)br=a.id;auto leaving=s.doc.bonds().alive(s.doc.incidentBonds(br).front());auto center=leaving->beginAtom==br?leaving->endAtom:leaving->beginAtom;auto loss=leaving->id;for(auto bid:s.doc.incidentBonds(center)){auto e=s.doc.bonds().alive(bid);auto n=e->beginAtom==center?e->endAtom:e->beginAtom;auto atom=s.doc.atoms().alive(n);if(atom->element==6&&s.doc.atomLabel(n).empty()&&s.doc.incidentBonds(n).size()==1){check(s.doc.setElement(n,1));auto h=s.doc.atoms().alive(n)->semantics;h.implicitHydrogens=0;check(s.doc.setAtomSemantics(n,h));break;}}
        if(bMirror)for(auto bid:s.doc.incidentBonds(center)){auto b=s.doc.bonds().alive(bid);auto v=projection_molecule::vector(s.doc,*b,center);std::ostringstream out;out.precision(17);out<<v.x<<' '<<v.y<<' '<<-v.z;s.doc.extensions(ObjectRef(ObjectKind::Bond,bid)).set(projection_molecule::vectorKey(*b,center),out.str());}
        std::string prefix=std::string(argv[2])+"/sn2-"+std::to_string(aMirror)+"-"+std::to_string(bMirror)+"-"+std::to_string(view);saveComponent(s.doc,center,prefix+"-source.cdxml");ObjectId oxygen;check(s.doc.addAtom(s.doc.atoms().alive(center)->position+Vec2(60,50),8,&oxygen));auto sem=s.doc.atoms().alive(oxygen)->semantics;sem.charge=-1;sem.implicitHydrogens=1;check(s.doc.setAtomSemantics(oxygen,sem));std::vector<ObjectRef> made;check(mechanism::generateNextStep(s.doc,{{ObjectRef(ObjectKind::Atom,oxygen),ObjectRef(ObjectKind::Atom,center)},{ObjectRef(ObjectKind::Bond,loss),ObjectRef(ObjectKind::Atom,br)}},&made));ObjectId product=kInvalidObjectId;for(auto ref:made)if(ref.kind==ObjectKind::Atom){auto raw=s.doc.extensions(ref).findValue("studio.mechanism.source.atom");if(raw&&std::strtoul(raw->c_str(),nullptr,10)==center)product=ref.id;}if(product==kInvalidObjectId)throw std::runtime_error("missing product");saveComponent(s.doc,product,prefix+"-product.cdxml");
    }std::cout<<"generated 20 SN2 R/S cases\n";
}catch(const std::exception& e){std::cerr<<e.what();code=3;}Gdiplus::GdiplusShutdown(token);return code;}
